.gmw-root[data-theme="light"] [data-name="Badge/Normal"] p,.gmw-root[data-theme="light"] [data-name^="status-normal"] p,.gmw-root[data-theme="light"] [data-name="Count/Normal"] p{color:var(--wa-text-sub, #4b5868)!important;font-weight:600;white-space:nowrap}
